import Foundation

/// 스토어에 올린 앱마다 QA할 때 볼 전용 항목. 번들 ID로 찾는다(대소문자 무시).
/// 각 앱의 README·문서·소스를 읽고 기능 전체를 도는 리그레션 목록으로 적었다.
/// 이 맥에 소스가 없는 네 앱(LeeoCon·TetraTint·여울·질문노트)만 스토어 설명에서 뽑은 5개짜리다.
/// 기본 체크리스트와 겹치는 것은 뺐다.
enum AppChecklistCatalog {
    static func key(_ bundleID: String) -> String {
        bundleID.trimmingCharacters(in: .whitespaces).lowercased()
    }

    static func items(for bundleID: String) -> [(ChecklistCategory, String, String)] {
        byKey[key(bundleID)] ?? []
    }

    private static let byKey: [String: [(ChecklistCategory, String, String)]] = Dictionary(
        uniqueKeysWithValues: itemsByBundleID.map { (key($0.key), $0.value) }
    )

    static let itemsByBundleID: [String: [(ChecklistCategory, String, String)]] = [
